/**
 * Host-mediated telemetry bridge for KAS mode.
 *
 * KAS runs as the ACP server in v3 mode, so telemetry generated by the
 * TUI must be forwarded to the Rust host explicitly. The hidden
 * `chat _ emit-telemetry` subcommand owns the Rust telemetry pipeline.
 */

import { type AsyncSpawner, runChatInternalAsync } from './chat-internal-cli';

export type KasTelemetryEvent =
  | 'kas-chat-slash-command'
  | 'kas-chat-session-started'
  | 'kas-mode-changed'
  | 'kas-process-health'
  | 'kas-turn-completion';

export type KasTelemetryResult = { ok: true } | { ok: false; message: string };

export function emitKasTelemetry(
  event: KasTelemetryEvent,
  payload: unknown,
  spawner?: AsyncSpawner
): Promise<KasTelemetryResult> {
  if (process.env.KIRO_TEST_MODE === 'true' && spawner === undefined) {
    return Promise.resolve({ ok: true });
  }

  const payloadJson = JSON.stringify(payload);
  if (payloadJson == null) {
    return Promise.resolve({
      ok: false,
      message: 'Failed to serialize KAS telemetry payload',
    });
  }

  return runChatInternalAsync(
    [
      'chat',
      '_',
      'emit-telemetry',
      '--event',
      event,
      '--payload-json',
      payloadJson,
    ],
    spawner,
    10_000
  ).then((result) => {
    if (!result.ok) return { ok: false, message: result.message };
    if (result.output.kind === 'error') {
      return { ok: false, message: result.output.data.message };
    }
    if (result.output.kind !== 'emitTelemetry') {
      return {
        ok: false,
        message: `Unexpected response kind from kiro-cli: ${result.output.kind}`,
      };
    }
    return { ok: true };
  });
}
